#!/bin/bash
# ABIX Cloner — manual CLI build (no Gradle): aapt2 + ecj + d8 + zipalign + apksigner
# Needs: JAVA_HOME (JDK/JRE 17+), ANDROID_HOME (SDK with build-tools 35.0.0 + platform android-35)
set -e
export PATH=$JAVA_HOME/bin:$PATH
ROOT=$(cd "$(dirname "$0")" && pwd)
BT=$ANDROID_HOME/build-tools/35.0.0
AJAR=$ANDROID_HOME/platforms/android-35/android.jar
B=$ROOT/build
LIBS=$ROOT/build-libs
mkdir -p $B/classes $B/dex $LIBS

# build libraries (downloaded once)
[ -f $LIBS/ecj.jar ] || curl -sL -o $LIBS/ecj.jar \
  "https://repo1.maven.org/maven2/org/eclipse/jdt/ecj/3.33.0/ecj-3.33.0.jar"
[ -f $LIBS/apksig.jar ] || curl -sL -o $LIBS/apksig.jar \
  "https://dl.google.com/dl/android/maven2/com/android/tools/build/apksig/8.7.2/apksig-8.7.2.jar"

# signing key: release builds are signed by ABIX; for your own build a key is
# generated on first run (alias "cloner", password below — change it if you like)
KS=$ROOT/cloner.p12
KS_PASS='AbixClone#2026'
if [ ! -f $KS ]; then
  keytool -genkeypair -keystore $KS -storetype PKCS12 -alias cloner -keyalg RSA \
    -keysize 2048 -validity 10000 -storepass "$KS_PASS" -keypass "$KS_PASS" \
    -dname "CN=ABIX Cloner, O=ABIX Lab, C=PK"
fi
mkdir -p $ROOT/app/assets
cp $KS $ROOT/app/assets/cloner.p12

# app icon: generated from an embedded copy if not present (keeps the repo text-only)
if [ ! -f $ROOT/app/res/drawable/icon.png ]; then
  mkdir -p $ROOT/app/res/drawable
  echo '' | base64 -d > $ROOT/app/res/drawable/icon.png
fi

echo "[1/6] aapt2 compile+link"
$BT/aapt2 compile --dir $ROOT/app/res -o $B/res.zip
$BT/aapt2 link -o $B/app-raw.apk -I $AJAR --manifest $ROOT/app/AndroidManifest.xml \
    -A $ROOT/app/assets --min-sdk-version 26 --target-sdk-version 34 $B/res.zip

echo "[2/6] compile java (app + engine)"
find $ROOT/app/src $ROOT/engine/src -name "*.java" ! -name "TestMain.java" > $B/sources.txt
$JAVA_HOME/bin/java -jar $LIBS/ecj.jar -1.8 -cp $AJAR:$LIBS/apksig.jar -d $B/classes @$B/sources.txt

echo "[3/6] d8 dex (app classes + apksig)"
python3 - << PYEOF
import zipfile, os
with zipfile.ZipFile('$B/classes.jar', 'w', zipfile.ZIP_DEFLATED) as z:
    for root, dirs, files in os.walk('$B/classes'):
        for f in files:
            p = os.path.join(root, f)
            z.write(p, os.path.relpath(p, '$B/classes'))
print('classes.jar written')
PYEOF
$BT/d8 --release --min-api 26 --lib $AJAR --output $B/dex $B/classes.jar $LIBS/apksig.jar

echo "[4/6] add classes.dex to apk"
python3 - << PYEOF
import zipfile, shutil
shutil.copy('$B/app-raw.apk', '$B/app-dex.apk')
with zipfile.ZipFile('$B/app-dex.apk', 'a') as z:
    z.write('$B/dex/classes.dex', 'classes.dex', zipfile.ZIP_DEFLATED)
print('dex added')
PYEOF

echo "[5/6] zipalign"
$BT/zipalign -f -p 4 $B/app-dex.apk $B/app-aligned.apk

echo "[6/6] sign"
$BT/apksigner sign --ks $KS --ks-pass "pass:$KS_PASS" --key-pass "pass:$KS_PASS" \
    --out $ROOT/ABIX-Cloner.apk $B/app-aligned.apk

echo "BUILD OK -> $ROOT/ABIX-Cloner.apk"
